import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"Capabilities","description":"The proposed research workflow and the limits of its first release.","frontmatter":{"title":"Capabilities","description":"The proposed research workflow and the limits of its first release."},"headers":[],"relativePath":"guide/capabilities.md","filePath":"guide/capabilities.md","lastUpdated":1794374806000}'),s={name:"guide/capabilities.md"};function o(n,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="what-the-system-is-designed-to-do" tabindex="-1">What the system is designed to do <a class="header-anchor" href="#what-the-system-is-designed-to-do" aria-label="Permalink to &quot;What the system is designed to do&quot;">​</a></h1><p><strong>These are target capabilities, not implemented features.</strong> Current deliverables are on the <a href="./../status">status page</a>.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What you would do</th><th>Design contract</th></tr></thead><tbody><tr><td>Acquire evidence</td><td>Import supported material; preserve its bytes, origin and processing history</td><td><a href="./../project/knowledge">Knowledge records</a></td></tr><tr><td>Resolve identities</td><td>Review aliases and possible matches without name-only merges</td><td><a href="./../project/knowledge#resolution-is-not-name-deduplication">Identity rules</a></td></tr><tr><td>Maintain claims</td><td>Keep qualified statements, supporting evidence and contradictions</td><td><a href="./../project/knowledge#confidence-and-disagreement">Confidence and disagreement</a></td></tr><tr><td>Publish deliberately</td><td>Approve an exact proposal and produce a traceable revision</td><td><a href="./../project/knowledge#atomic-publication">Atomic publication</a></td></tr><tr><td>Ask with evidence</td><td>Combine available lexical, vector and graph retrieval; stream a cited answer</td><td><a href="./../project/streaming">Research interface</a></td></tr><tr><td>Observe work</td><td>Inspect progress, missing capabilities, retries and review requests</td><td><a href="./../project/plugins#durable-task-state">Durable jobs</a></td></tr><tr><td>Move the library</td><td>Export a verified package and reopen it without the original machine</td><td><a href="./../project/knowledge#portable-package">Portable package</a></td></tr><tr><td>Extend processing</td><td>Add compatible Rust or Swift workers for models, audio or media</td><td><a href="./../project/plugins">Worker contracts</a></td></tr></tbody></table><h2 id="four-useful-distinctions" tabindex="-1">Four useful distinctions <a class="header-anchor" href="#four-useful-distinctions" aria-label="Permalink to &quot;Four useful distinctions&quot;">​</a></h2><p><strong>A mention is not an entity.</strong> A name in a report needs contextual resolution.</p><p><strong>A copy is not an independent confirmation.</strong> Repeated copies of one account do not become separate witnesses.</p><p><strong>A draft is not published knowledge.</strong> Public retrieval uses an approved revision; draft access is explicit.</p><p><strong>A disconnected stream is not a finished answer.</strong> Completion, refusal, cancellation and interruption remain distinct outcomes.</p><h2 id="first-release-versus-later" tabindex="-1">First release versus later <a class="header-anchor" href="#first-release-versus-later" aria-label="Permalink to &quot;First release versus later&quot;">​</a></h2><p>The first complete release targets a small text/structured-data collection, reviewed publication, evidence-backed retrieval, streaming chat and portable export. Deterministic fixtures make contracts testable before real model adapters are enabled.</p><p>Native video, broader connectors and multi-machine authoring reconciliation come later. A plugin interface does not mean every backend exists or produces equivalent results.</p><p><strong>Next:</strong> <a href="./walkthrough">Walk through one research case →</a></p>',12)])])}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
